import { expect, expectStatus, test } from "../../fixtures";

test("Approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in review with three pending extractions, reviewed as the reviewer persona.
  const reviewer = await apiAs("reviewer");
  const { vendor, documents, extractions } = await factory.vendorInReview();

  // Act: approve all three extractions.
  for (const extraction of Object.values(extractions)) {
    const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
      data: { decision: "approve" },
    });
    await expectStatus(response, 200);
  }

  // Assert: each extraction is stored as approved (re-read, not the decision echo).
  for (const document of Object.values(documents)) {
    expect((await factory.extraction(document.id, "reviewer")).status).toBe("approved");
  }

  // Assert: the vendor becomes approved. Re-read until the background update lands.
  await expect
    .poll(async () => (await expectStatus<{ status: string }>(await reviewer.get(`/api/vendors/${vendor.id}`), 200)).status, {
      message: "vendor status becomes approved",
      timeout: 15_000,
    })
    .toBe("approved");

  // Assert: the audit trail records vendor.approved.
  await expect
    .poll(
      async () => {
        const trail = await expectStatus<{ items: { action: string }[] }>(
          await reviewer.get(`/api/vendors/${vendor.id}/audit`),
          200,
        );
        return trail.items.map((event) => event.action);
      },
      { message: "audit event vendor.approved is recorded", timeout: 15_000 },
    )
    .toContain("vendor.approved");
});
